<?php require_once __DIR__.'/chart_local.php'; function jobstatplot($width=650,$height=400){$r=db_query("SELECT v.description,SUM(jh.entries) FROM job_history jh JOIN validation v ON jh.validationfk=v.ref WHERE jh.mode='r' AND jh.date>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 3 WEEK) GROUP BY v.description ORDER BY SUM(jh.entries) DESC",'ro');$d=[];while($x=mysqli_fetch_row($r))$d[]=[$x[0],(float)$x[1]];echo '<div id="jobstatchart_div">'.atlas_chart_bars($d,'Installation Job Status',$width,$height).'</div>';}
